import { MakeLogicType, afterMount, kea, key, listeners, path, props } from 'kea'
import { loaders } from 'kea-loaders'

import { lemonToast } from 'lib/lemon-ui/LemonToast'

import { desktopBetaTermsCreate, desktopBetaTermsList } from 'products/tasks/frontend/generated/api'

export interface DesktopBetaTermsLogicProps {
    organizationId: string
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface desktopBetaTermsLogicValues {
    desktopBetaTermsAccepted: boolean | null
    desktopBetaTermsAcceptedLoading: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface desktopBetaTermsLogicActions {
    acceptDesktopBetaTerms: () => any
    acceptDesktopBetaTermsFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    acceptDesktopBetaTermsSuccess: (
        desktopBetaTermsAccepted: boolean,
        payload?: any
    ) => {
        desktopBetaTermsAccepted: boolean
        payload?: any
    }
    loadDesktopBetaTermsAccepted: () => any
    loadDesktopBetaTermsAcceptedFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadDesktopBetaTermsAcceptedSuccess: (
        desktopBetaTermsAccepted: boolean,
        payload?: any
    ) => {
        desktopBetaTermsAccepted: boolean
        payload?: any
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface desktopBetaTermsLogicMeta {
    key: string
}

export type desktopBetaTermsLogicType = MakeLogicType<
    desktopBetaTermsLogicValues,
    desktopBetaTermsLogicActions,
    DesktopBetaTermsLogicProps,
    desktopBetaTermsLogicMeta
>

export const desktopBetaTermsLogic = kea<desktopBetaTermsLogicType>([
    props({} as DesktopBetaTermsLogicProps),
    key((props) => props.organizationId),
    path((key) => ['scenes', 'settings', 'organization', 'desktopBetaTermsLogic', key]),
    loaders(({ props }) => ({
        desktopBetaTermsAccepted: [
            null as boolean | null,
            {
                loadDesktopBetaTermsAccepted: async () => {
                    const response = await desktopBetaTermsList(props.organizationId)
                    return response.is_desktop_beta_terms_accepted
                },
                acceptDesktopBetaTerms: async () => {
                    const response = await desktopBetaTermsCreate(props.organizationId)
                    return response.is_desktop_beta_terms_accepted
                },
            },
        ],
    })),
    listeners(() => ({
        loadDesktopBetaTermsAcceptedFailure: () => {
            lemonToast.error('Could not load the PostHog Desktop beta terms status. Please try again.')
        },
        acceptDesktopBetaTermsSuccess: () => {
            lemonToast.success('PostHog Desktop beta terms accepted')
        },
        acceptDesktopBetaTermsFailure: () => {
            lemonToast.error('Could not accept the PostHog Desktop beta terms. Please try again.')
        },
    })),
    afterMount(({ actions }) => {
        actions.loadDesktopBetaTermsAccepted()
    }),
])
